struct Mask{array<uint64_t,W>w{};bool operator==(Mask const&o)const{return w==o.w;}};struct MH{size_t operator()(Mask const&m)const noexcept{uint64_t h=1469598103934665603ULL;for(auto x:m.w){h^=x;h*=1099511628211ULL;}return h;}};inline void sb(Mask&m,int x){m.w[x>>6]|=1ULL<<(x&63);} inline bool disj(const Mask&a,const Mask&b){for(int i=0;i<W;i++)if(a.w[i]&b.w[i])return false;return true;}Mask tf(const Mask&k,const vector<int>&g){Mask y;for(int wi=0;wi<W;wi++){uint64_t x=k.w[wi];while(x){int b=__builtin_ctzll(x);x&=x-1;int r=64*wi+b;if(r<NF)sb(y,g[r]);}}return y;}struct Sig{array<uint64_t,3>w{};bool operator==(Sig const&o)const{return w==o.w;}};struct SH{size_t operator()(Sig const&s)const noexcept{return s.w[0]^(s.w[1]*0x9e3779b97f4a7c15ULL)^(s.w[2]*0xbf58476d1ce4e5b9ULL);}};Sig packs(const array<int,45>&a){Sig s;for(int i=0;i<45;i++)s.w[i/16]|=(uint64_t)a[i]<<(4*(i%16));return s;}
int main(int argc,char**argv){if(argc!=7){cerr<<"usage group.in reps.bin frame_octet.txt signatures.json tuples.json out.json\n";return 2;}ifstream fi(argv[1]);int nr,ne,ng,z;fi>>nr>>ne>>ng;for(int i=0;i<nr*4;i++)fi>>z;vector<vector<int>>gens(ng,vector<int>(NF));for(auto&g:gens)for(int&i:g)fi>>i;vector<vector<int>>G;vector<int>id(NF);iota(id.begin(),id.end(),0);unordered_set<string>ps;auto pk=[](auto const&p){return string((char*)p.data(),p.size()*sizeof(int));};G.push_back(id);ps.insert(pk(id));for(size_t h=0;h<G.size();h++)for(auto&g:gens){vector<int>q(NF);for(int i=0;i<NF;i++)q[i]=g[G[h][i]];if(ps.insert(pk(q)).second)G.push_back(move(q));}ifstream rb(argv[2],ios::binary);uint64_t nrep;rb.read((char*)&nrep,8);vector<Mask>reps(nrep);for(size_t i=0;i<nrep;i++){for(int j=0;j<60;j++){uint16_t x;rb.read((char*)&x,2);sb(reps[i],x);}uint32_t dummy;rb.read((char*)&dummy,4);rb.read((char*)&dummy,4);rb.read((char*)&dummy,4);}unordered_set<Mask,MH>cs;cs.reserve(4200000);for(auto&r:reps)for(auto&g:G)cs.insert(tf(r,g));vector<Mask>covers(cs.begin(),cs.end());if(covers.size()!=3547800)return 3;vector<int>key(NF);{ifstream f(argv[3]);for(int&i:key)f>>i;}string ss;{ifstream f(argv[4]);ss.assign((istreambuf_iterator<char>(f)),{});}vector<array<int,45>>raw;vector<int>expect;size_t p=0;while((p=ss.find("\"count\":",p))!=string::npos){p+=8;expect.push_back(stoi(ss.substr(p)));p=ss.find("\"vector\":[",p)+10;array<int,45>a{};for(int q=0;q<45;q++){a[q]=stoi(ss.substr(p));p=ss.find(q==44?']':',',p)+1;}raw.push_back(a);}unordered_map<Sig,int,SH>sid;for(int i=0;i<720;i++)sid[packs(raw[i])]=i;vector<vector<int>>fib(720);for(int ci=0;ci<(int)covers.size();ci++){array<int,45>a{};for(int wi=0;wi<W;wi++){uint64_t x=covers[ci].w[wi];while(x){int b=__builtin_ctzll(x);x&=x-1;int f=wi*64+b;if(f<NF)a[key[f]]++;}}fib[sid.at(packs(a))].push_back(ci);}for(int i=0;i<720;i++)if((int)fib[i].size()!=expect[i])return 6;string ts;{ifstream f(argv[5]);ts.assign((istreambuf_iterator<char>(f)),{});}vector<array<int,9>>tuples;size_t tp=ts.find("\"tuples\":[");tp=ts.find('[',tp+9)+1;while(tp<ts.size()){tp=ts.find('[',tp);if(tp==string::npos)break;array<int,9>t{};size_t q=tp+1;bool ok=1;for(int i=0;i<9;i++){while(q<ts.size()&&!isdigit((unsigned char)ts[q]))q++;if(q>=ts.size()){ok=0;break;}t[i]=stoi(ts.substr(q));q=ts.find(i==8?']':',',q)+1;}if(!ok)break;tuples.push_back(t);tp=q;if(tuples.size()>=33)break;}map<pair<int,int>,uint64_t>cache;auto paircount=[&](int a,int b)->uint64_t{if(a>b)swap(a,b);auto P=make_pair(a,b);if(cache.count(P))return cache[P];uint64_t cnt=0;for(int x:fib[a])for(int y:fib[b])if(disj(covers[x],covers[y]))cnt++;return cache[P]=cnt;};ofstream o(argv[6]);o<<"{\"global_covers\":"<<covers.size()<<",\"all_720_fibers_validated\":true,\"tuple_results\":[";bool fst=1;int blocked=0;for(int ti=0;ti<(int)tuples.size();ti++){auto t=tuples[ti];vector<tuple<long long,int,int>>pairs;for(int i=0;i<9;i++)for(int j=i+1;j<9;j++)pairs.push_back({(long long)fib[t[i]].size()*fib[t[j]].size(),t[i],t[j]});sort(pairs.begin(),pairs.end());int za=-1,zb=-1,tested=0;for(auto[prod,a,b]:pairs){tested++;if(paircount(a,b)==0){za=a;zb=b;break;}}if(za>=0)blocked++;if(!fst)o<<",";fst=0;o<<"{\"tuple_index\":"<<ti<<",\"blocked\":"<<(za>=0?"true":"false")<<",\"pairs_tested\":"<<tested;if(za>=0)o<<",\"zero_pair\":["<<za<<","<<zb<<"]";o<<"}";}o<<"],\"blocked_tuples\":"<<blocked<<",\"total_tuples\":"<<tuples.size()<<",\"pair_relations_computed\":"<<cache.size()<<"}\n";}
